{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "GSK1322322 showed absolute oral bioavailability of 77% in healthy volunteers after a meal, directly supporting F >= 20% for a small-molecule oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, an oral kinase inhibitor with aminopyrimidine and piperazine-like features, had mean absolute bioavailability of 98% in humans, supporting high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Risdiplam has high oral bioavailability due to complete absorption and negligible first-pass extraction in human mass-balance and DDI studies, supporting high F for a heteroaromatic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brepocitinib had an estimated absolute bioavailability of 75% in humans, providing direct human evidence for high oral F in a small-molecule heteroaromatic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Predicted human pharmacokinetics for a cyclopentyl-containing heteroaromatic analogue indicated 80% oral bioavailability, supporting high F for the query's N-cyclopentyl scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues report oral bioavailability at or above the F >= 20% threshold, mostly in the 46-98% range or described as high, and no affirmative low-F evidence was retrieved. The query is therefore predicted to have high oral bioavailability, with moderate confidence due to modest structural similarity.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "Morgan similarities to the evidence molecules are modest (0.22-0.38), limiting structural transferability.",
    "No retrieved evidence specifically addresses the query's piperazine/pyridopyrimidine system for possible efflux or first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

